-- Specialized current-schema Purchase Order test baseline.
-- Derived from the application migration source; contains schema only, no business data.
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE `languages` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `name` VARCHAR(255) NOT NULL, `code` VARCHAR(255) NOT NULL, `country_name` VARCHAR(255) NOT NULL, `is_default` TINYINT(1) NOT NULL DEFAULT 0 COMMENT 'true mins application default language', `created_at` TIMESTAMP NULL DEFAULT NULL, `updated_at` TIMESTAMP NULL DEFAULT NULL, `create_by` VARCHAR(255) NULL DEFAULT NULL, `update_by` VARCHAR(255) NULL DEFAULT NULL, `delete_by` VARCHAR(255) NULL DEFAULT NULL, `deleted_at` TIMESTAMP NULL DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `languages_name_unique` (`name`), UNIQUE KEY `languages_code_unique` (`code`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `role_manages` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `name` VARCHAR(255) NOT NULL, `content` LONGTEXT NOT NULL, `create_by` VARCHAR(255) NULL DEFAULT NULL, `update_by` VARCHAR(255) NULL DEFAULT NULL, `delete_by` VARCHAR(255) NULL DEFAULT NULL, `created_at` TIMESTAMP NULL DEFAULT NULL, `updated_at` TIMESTAMP NULL DEFAULT NULL, `deleted_at` TIMESTAMP NULL DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `role_manages_name_unique` (`name`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `users` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `name` VARCHAR(255) NOT NULL, `email` VARCHAR(255) NOT NULL, `role_manage_id` INT NOT NULL DEFAULT 5, `language_id` BIGINT UNSIGNED NULL DEFAULT NULL, `email_verified_at` TIMESTAMP NULL DEFAULT NULL, `password` VARCHAR(255) NOT NULL, `create_by` VARCHAR(255) NULL DEFAULT NULL, `update_by` VARCHAR(255) NULL DEFAULT NULL, `delete_by` VARCHAR(255) NULL DEFAULT NULL, `deleted_at` TIMESTAMP NULL DEFAULT NULL, `remember_token` VARCHAR(100) NULL DEFAULT NULL, `created_at` TIMESTAMP NULL DEFAULT NULL, `updated_at` TIMESTAMP NULL DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `users_email_unique` (`email`), CONSTRAINT `users_language_id_foreign` FOREIGN KEY (`language_id`) REFERENCES `languages` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `settings` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `settings_name` VARCHAR(255) NULL DEFAULT NULL, `content` LONGTEXT NULL, `header_image` VARCHAR(255) NULL DEFAULT NULL, `vat_percentage` DECIMAL(5,2) NOT NULL DEFAULT 0.00, `company_color` VARCHAR(255) NOT NULL DEFAULT '#00897B', `created_at` TIMESTAMP NULL DEFAULT NULL, `updated_at` TIMESTAMP NULL DEFAULT NULL, `deleted_at` TIMESTAMP NULL DEFAULT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `branches` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `name` VARCHAR(255) NOT NULL, `location` LONGTEXT NULL, `description` LONGTEXT NULL, `create_by` VARCHAR(255) NULL DEFAULT NULL, `update_by` VARCHAR(255) NULL DEFAULT NULL, `delete_by` VARCHAR(255) NULL DEFAULT NULL, `created_at` TIMESTAMP NULL DEFAULT NULL, `updated_at` TIMESTAMP NULL DEFAULT NULL, `deleted_at` TIMESTAMP NULL DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `branches_name_unique` (`name`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `inventory_types` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `name` VARCHAR(255) NOT NULL, `created_at` TIMESTAMP NULL DEFAULT NULL, `updated_at` TIMESTAMP NULL DEFAULT NULL, `deleted_at` TIMESTAMP NULL DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `inventory_types_name_unique` (`name`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `inventories` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `type_id` BIGINT UNSIGNED NULL DEFAULT NULL, `branch_id` INT UNSIGNED NULL DEFAULT NULL, `description` TEXT NULL, `sub_item` VARCHAR(255) NULL DEFAULT NULL, `unit_of_measurement` VARCHAR(255) NOT NULL, `unit_cost` DECIMAL(15,2) NOT NULL, `sale_price` DECIMAL(15,2) NOT NULL, `quantity_at_hand` INT NOT NULL, `reorder_level` INT UNSIGNED NOT NULL DEFAULT 0, `account` VARCHAR(255) NOT NULL, `created_at` TIMESTAMP NULL DEFAULT NULL, `updated_at` TIMESTAMP NULL DEFAULT NULL, `deleted_at` TIMESTAMP NULL DEFAULT NULL, PRIMARY KEY (`id`), CONSTRAINT `inventories_type_id_foreign` FOREIGN KEY (`type_id`) REFERENCES `inventory_types` (`id`) ON DELETE SET NULL, CONSTRAINT `inventories_branch_id_foreign` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `vendors` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `branch_id` INT UNSIGNED NULL DEFAULT NULL, `reg_number` VARCHAR(255) NOT NULL, `name` VARCHAR(255) NOT NULL, `address` VARCHAR(255) NOT NULL, `phone_number` VARCHAR(255) NOT NULL, `account` VARCHAR(255) NOT NULL, `terms_of_payment` VARCHAR(255) NOT NULL, `created_at` TIMESTAMP NULL DEFAULT NULL, `updated_at` TIMESTAMP NULL DEFAULT NULL, `deleted_at` TIMESTAMP NULL DEFAULT NULL, PRIMARY KEY (`id`), CONSTRAINT `vendors_branch_id_foreign` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `sessions` (`id` VARCHAR(255) NOT NULL, `user_id` BIGINT UNSIGNED NULL DEFAULT NULL, `ip_address` VARCHAR(45) NULL DEFAULT NULL, `user_agent` TEXT NULL, `payload` TEXT NOT NULL, `last_activity` INT NOT NULL, PRIMARY KEY (`id`), KEY `sessions_user_id_index` (`user_id`), KEY `sessions_last_activity_index` (`last_activity`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `invoice_sequences` (`document_type` VARCHAR(32) NOT NULL, `current_number` INT UNSIGNED NOT NULL DEFAULT 0, `created_at` TIMESTAMP NULL DEFAULT NULL, `updated_at` TIMESTAMP NULL DEFAULT NULL, `deleted_at` TIMESTAMP NULL DEFAULT NULL, PRIMARY KEY (`document_type`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
